"use client";

import { useId } from "react";
import { valueRange } from "./skeuo-value-range";
import "./styles/skeuo-stepper.css";

export type SkeuoStepperProps = {
  label: string;
  value: number;
  onValueChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  formatValue?: (value: number) => string;
};

export function SkeuoStepper({
  label, value, onValueChange, min = 0, max = 99, step = 1,
  disabled = false, formatValue = (number) => String(number).padStart(number >= 0 ? 2 : 0, "0"),
}: SkeuoStepperProps) {
  const id = useId();
  const range = valueRange(min, max, step);
  const current = range.clamp(value);
  const previous = range.move(current, -1);
  const next = range.move(current, 1);

  return (
    <div className="sk-stepper" data-sk-root="" role="group" aria-labelledby={id} data-disabled={disabled || undefined}>
      <span className="sk-stepper-label" id={id}>{label}</span>
      <div className="sk-stepper-tray">
        <button type="button" aria-label={`Decrease ${label}`} disabled={disabled || previous >= current} onClick={() => onValueChange(previous)}><span aria-hidden="true">−</span></button>
        <output className="sk-stepper-readout" aria-labelledby={id}><span>{formatValue(current)}</span></output>
        <button type="button" aria-label={`Increase ${label}`} disabled={disabled || next <= current} onClick={() => onValueChange(next)}><span aria-hidden="true">+</span></button>
      </div>
    </div>
  );
}

export function valueRange(min: number, max: number, step: number) {
  const lower = Number.isFinite(min) ? min : 0;
  const upper = Number.isFinite(max) && max >= lower ? max : lower;
  const increment = Number.isFinite(step) && step > 0 ? step : 1;

  function clamp(value: number) {
    return Number.isFinite(value) ? Math.min(upper, Math.max(lower, value)) : lower;
  }

  function atStep(index: number) {
    return clamp(Number((lower + index * increment).toPrecision(15)));
  }

  function nearest(value: number) {
    const bounded = clamp(value);
    return bounded === upper ? upper : atStep(Math.round((bounded - lower) / increment));
  }

  function move(value: number, steps: number) {
    const offset = (clamp(value) - lower) / increment;
    const index = Number(offset.toPrecision(15));
    return atStep(steps > 0 ? Math.floor(index) + steps : Math.ceil(index) + steps);
  }

  return { min: lower, max: upper, clamp, nearest, move };
}

@import "./skeuo-base.css";

:where(:root, .light, [data-theme="light"]) {
  --sk-stepper-glass: #d9e4d9;
  --sk-stepper-glass-edge: #64796b;
  --sk-stepper-glass-rim: #aabdad;
  --sk-stepper-glass-ink: #20392e;
}
:where(.dark, [data-theme="dark"]) {
  --sk-stepper-glass: #a2b8a8;
  --sk-stepper-glass-edge: #486455;
  --sk-stepper-glass-rim: #708d7d;
  --sk-stepper-glass-ink: #15271d;
}
@media (prefers-color-scheme: dark) {
  :where(html:not(.light):not(.dark):not([data-theme])) {
    --sk-stepper-glass: #a2b8a8;
    --sk-stepper-glass-edge: #486455;
    --sk-stepper-glass-rim: #708d7d;
    --sk-stepper-glass-ink: #15271d;
  }
}

.sk-stepper {
  --sk-stepper-body: color-mix(in srgb, var(--sk-surface) 91%, #c8a575);
  --sk-stepper-lip: color-mix(in srgb, var(--sk-base) 84%, #aa8d66);
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 23px;
  width: min(100%, 358px);
  min-height: 194px;
  padding: 22px clamp(9px, 4vw, 23px) 28px;
  border: 1px solid var(--sk-stepper-lip);
  border-radius: 20px;
  background: linear-gradient(150deg, var(--sk-surface-raised), var(--sk-stepper-body));
  color: var(--sk-card-ink);
  box-shadow: inset 0 2px var(--sk-highlight), inset 0 -3px var(--sk-stepper-lip),
    0 4px var(--sk-base), 0 5px var(--sk-edge), 0 8px 12px #0002;
}
.sk-stepper-label { font-size: 22px; font-weight: 650; overflow-wrap: anywhere; }
.sk-stepper-tray {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  width: 100%;
  padding: 11px 9px 12px;
  border: 1px solid var(--sk-stepper-lip);
  border-radius: 16px;
  background: linear-gradient(155deg, var(--sk-surface-raised), var(--sk-stepper-lip));
  box-shadow: inset 0 2px var(--sk-highlight), inset 0 -2px 2px #0002,
    0 3px var(--sk-stepper-lip), 0 4px 5px #0002;
}
.sk-stepper-tray::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 5px;
  border-radius: 11px;
  background: var(--sk-well);
  box-shadow: inset 0 3px 6px #0004, inset 2px 0 4px #0003, 0 1px var(--sk-highlight);
}
.sk-stepper-tray button {
  --sk-stepper-key-top: var(--sk-surface-raised);
  --sk-stepper-key-face: var(--sk-stepper-body);
  --sk-stepper-key-base: color-mix(in srgb, var(--sk-key-base) 80%, #7b6a53);
  --sk-stepper-key-edge: color-mix(in srgb, var(--sk-key-edge) 70%, #625a4e);
  --sk-stepper-key-height: 7px;
  display: grid;
  width: clamp(44px, 14vw, 66px);
  min-height: 62px;
  padding: 1px 1px var(--sk-stepper-key-height);
  border: 1px solid var(--sk-stepper-key-edge);
  border-radius: 11px;
  background: linear-gradient(160deg, var(--sk-stepper-key-face), var(--sk-stepper-key-base) 58%);
  color: var(--sk-ink);
  box-shadow: inset 0 -1px 2px #0006, 0 1px 1px #0006, 1px 3px 4px #0003;
  font: 600 27px/1 var(--sk-font-mono);
  cursor: pointer;
}
.sk-stepper-tray button > span {
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: linear-gradient(145deg, var(--sk-stepper-key-top), var(--sk-stepper-key-face) 70%);
  box-shadow: inset 0 2px 1px #ffffff66, inset 0 -2px 2px #0002, inset -1px 0 2px #0002,
    0 1px 2px #0004;
}
.sk-stepper-tray button:last-child {
  --sk-stepper-key-top: var(--sk-accent-bright);
  --sk-stepper-key-face: var(--sk-accent);
  --sk-stepper-key-base: var(--sk-accent-base);
  --sk-stepper-key-edge: var(--sk-accent-edge);
  color: var(--sk-accent-ink);
}
.sk-stepper-tray button:active:not(:disabled) {
  transform: translateY(4px);
  box-shadow: inset 0 -1px 2px #0008, 0 1px 2px #0004;
}
.sk-stepper-tray button:focus-visible { outline: 2px solid var(--sk-ring); outline-offset: 3px; }
.sk-stepper-tray button:disabled { opacity: .45; cursor: not-allowed; }

.sk-stepper-readout {
  display: grid;
  min-width: 0;
  padding: 3px;
  border: 1px solid var(--sk-stepper-glass-edge);
  border-radius: 10px;
  background: linear-gradient(var(--sk-stepper-glass-edge), var(--sk-stepper-glass-rim) 58%, var(--sk-stepper-glass));
  box-shadow: 0 1px var(--sk-highlight), 0 -1px 2px #0005;
}
.sk-stepper-readout > span {
  display: grid;
  min-width: 0;
  place-items: center;
  padding: 9px 4px 6px;
  overflow-wrap: anywhere;
  text-align: center;
  border: 1px solid var(--sk-stepper-glass-edge);
  border-radius: 7px;
  background: radial-gradient(ellipse at 52% 82%, var(--sk-stepper-glass) 30%, var(--sk-stepper-glass-rim));
  color: var(--sk-stepper-glass-ink);
  text-shadow: 0 1px #ffffff60;
  box-shadow: inset 0 5px 7px #15271d55, inset 4px 0 6px #15271d45, inset -3px 0 5px #15271d30,
    inset 0 -2px 1px #ffffff94;
  font: 650 clamp(19px, 7vw, 30px)/1 var(--sk-font-mono);
  font-variant-numeric: tabular-nums;
}
.sk-stepper[data-disabled] .sk-stepper-readout { opacity: .55; }

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
